describe('Search Results Debounce Functionality', () => {
  const API_DELAY = 300;
  const DEBOUNCE_BUFFER = 100;
  const searchUrl = '/api/search';
  const baseUrl = 'http://localhost:3000';

  beforeEach(() => {
    cy.visit(`${baseUrl}/search`);
    cy.intercept('GET', `${searchUrl}*`, (req) => {
      req.reply((res) => {
        res.delay(50);
      });
    }).as('searchRequest');
  });

  it('should debounce search requests by 300ms when typing', () => {
    const searchTerm = 'cypress testing';
    const requestTimestamps = [];

    cy.intercept('GET', `${searchUrl}*`, (req) => {
      requestTimestamps.push(Date.now());
      req.reply({
        statusCode: 200,
        body: {
          results: [
            { id: 1, title: 'Test Result 1' },
            { id: 2, title: 'Test Result 2' }
          ]
        }
      });
    }).as('debouncedSearch');

    cy.get('[data-testid="search-input"]').as('searchInput');

    cy.get('@searchInput').type('c', { delay: 50 });
    cy.get('@searchInput').type('y', { delay: 50 });
    cy.get('@searchInput').type('p', { delay: 50 });
    cy.get('@searchInput').type('r', { delay: 50 });
    cy.get('@searchInput').type('e', { delay: 50 });
    cy.get('@searchInput').type('s', { delay: 50 });
    cy.get('@searchInput').type('s', { delay: 50 });

    cy.wait('@debouncedSearch').then(() => {
      expect(requestTimestamps.length).to.equal(1);
    });

    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-results"] li').should('have.length', 2);
  });

  it('should make multiple requests when typing pauses exceed debounce threshold', () => {
    const requestCount = [];

    cy.intercept('GET', `${searchUrl}*`, (req) => {
      requestCount.push(1);
      req.reply({
        statusCode: 200,
        body: {
          results: [{ id: 1, title: 'Result for ' + req.url }]
        }
      });
    }).as('multiSearch');

    cy.get('[data-testid="search-input"]').as('searchInput');

    cy.get('@searchInput').type('test', { delay: 50 });
    cy.wait(API_DELAY + DEBOUNCE_BUFFER);
    cy.wait('@multiSearch');

    cy.get('@searchInput').type('ing', { delay: 50 });
    cy.wait(API_DELAY + DEBOUNCE_BUFFER);
    cy.wait('@multiSearch');

    cy.then(() => {
      expect(requestCount.length).to.equal(2);
    });

    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should handle rapid clearing and retyping with proper debouncing', () => {
    const requestLog = [];

    cy.intercept('GET', `${searchUrl}*`, (req) => {
      requestLog.push({
        query: new URL(req.url, baseUrl).searchParams.get('q'),
        timestamp: Date.now()
      });
      req.reply({
        statusCode: 200,
        body: { results: [] }
      });
    }).as('clearSearch');

    cy.get('[data-testid="search-input"]').as('searchInput');

    cy.get('@searchInput').type('initial', { delay: 50 });
    cy.wait(API_DELAY + DEBOUNCE_BUFFER);
    cy.wait('@clearSearch');

    cy.get('@searchInput').clear();
    cy.wait(API_DELAY + DEBOUNCE_BUFFER);
    cy.wait('@clearSearch');

    cy.get('@searchInput').type('new', { delay: 50 });
    cy.wait(API_DELAY + DEBOUNCE_BUFFER);
    cy.wait('@clearSearch');

    cy.then(() => {
      expect(requestLog.length).to.equal(3);
    });
  });

  it('should display loading state during debounce period', () => {
    cy.intercept('GET', `${searchUrl}*`, (req) => {
      req.reply((res) => {
        res.delay(200);
      });
    }).as('delayedSearch');

    cy.get('[data-testid="search-input"]').type('load', { delay: 50 });

    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    cy.wait('@delayedSearch');

    cy.get('[data-testid="loading-indicator"]').should('not.be.visible');
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should handle empty search results gracefully', () => {
    cy.intercept('GET', `${searchUrl}*`, {
      statusCode: 200,
      body: { results: [] }
    }).as('emptySearch');

    cy.get('[data-testid="search-input"]').type('nonexistent', { delay: 50 });

    cy.wait(API_DELAY + DEBOUNCE_BUFFER);
    cy.wait('@emptySearch');

    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="search-results"] li').should('have.length', 0);
  });

  it('should cancel previous request when new input arrives before debounce completes', () => {
    let requestCount = 0;

    cy.intercept('GET', `${searchUrl}*`, (req) => {
      requestCount++;
      req.reply({
        statusCode: 200,
        body: { results: [{ id: requestCount, title: `Result ${requestCount}` }] }
      });
    }).as('cancelableSearch');

    cy.get('[data-testid="search-input"]').as('searchInput');

    cy.get('@searchInput').type('a', { delay: 50 });
    cy.wait(150);
    cy.get('@searchInput').type('b', { delay: 50 });
    cy.wait(150);
    cy.get('@searchInput').type('c', { delay: 50 });

    cy.wait(API_DELAY + DEBOUNCE_BUFFER);
    cy.wait('@cancelableSearch');

    cy.then(() => {
      expect(requestCount).to.equal(1);
    });
  });
});
